import { Column, Entity, Index, PrimaryGeneratedColumn } from 'typeorm';

/**
 * A user's project: optionally connected to one repository, soft-deleted through `deletedAt` +
 * `deletedToken` (`0` while live, the project's `id` once deleted). Owns table `issues_projects`
 * (see `docs/agents/specs/issues/model.md#issues_projects`). `userId` and `repositoryId` are
 * logical FKs only: no relation, no join. `uuid` is generated by the service at insert.
 */
@Entity('issues_projects')
@Index('idx_issues_projects_user_id_name_deleted_token', ['userId', 'name', 'deletedToken'], { unique: true })
@Index('idx_issues_projects_user_id_repository_id_deleted_token', ['userId', 'repositoryId', 'deletedToken'], { unique: true })
@Index('idx_issues_projects_uuid', ['uuid'], { unique: true })
export class IssuesProject {
  @PrimaryGeneratedColumn()
    id!: number;

  @Column({ type: 'char', length: 36 })
    uuid!: string;

  @Column({ name: 'user_id', type: 'int' })
    userId!: number;

  @Column({ type: 'varchar', length: 100 })
    name!: string;

  @Column({ type: 'varchar', length: 2000, nullable: true })
    description!: string | null;

  @Column({ name: 'repository_id', type: 'int', nullable: true })
    repositoryId!: number | null;

  @Column({ name: 'deleted_at', type: 'datetime', nullable: true })
    deletedAt!: Date | null;

  @Column({ name: 'deleted_token', type: 'int', default: 0 })
    deletedToken!: number;

  @Column({ name: 'created_at', type: 'datetime' })
    createdAt!: Date;

  @Column({ name: 'updated_at', type: 'datetime' })
    updatedAt!: Date;
}
